p {
  margin: 0;
}

.questionLink {
  width: 100%;
  height: auto;
  font-size: min(16px, 3vw);
}

.questionLink .head .head__text {
  font-size: 1.2em;
  text-align: center;
  font-weight: bold;
}

.questionLink .image,
.questionLink .link {
  margin-top: 1em;
  width: 100%;
}

.questionLink .image img,
.questionLink .image video {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.questionLink .image *+* {
  margin-top: 1em !important;
}

.questionLink .link .link__button {
  width: 100%;
  height: auto;
  display: block;
  background: #EC5B38;
  border-radius: 10px;
  padding: 0.8em 0.5em;
  border-bottom: 6px solid #b63a1b;
  box-sizing: border-box;
  color: #fff;
  text-decoration: none;
  text-align: center;
  font-size: 1.2em;
  font-weight: bold;
}

.questionLink .link .link__button .sub {
  color: #ecc238;
  font-size: 0.8em;
  display: block;
}

.footer {
  margin-top: 3em;
  padding-top: 1em;
  border-top: 2px solid #ccc;
}

.footer__logo {
  width: 20%;
  height: auto;
}

.footer__logo img {
  width: 100%;
  height: auto;
}

.footer__list {
  margin-top: 1em;
  padding-left: 0;
  width: 90%;
  height: auto;
  margin: 1em auto 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  list-style: none;
}

.footer__list li {
  width: 30%;
  height: auto;
  font-size: 0.85em;
}

.footer__list li:before {
  content: '>';
  padding-right: 0.5em;
}

.footer__list li a {
  font-size: 1em;
  color: #7692FF;
}

.footer .copyright {
  background: #A8A492;
  width: 100%;
  height: auto;
  padding: 0.5em 0;
  margin-top: 1em;
}

.footer .copyright .copyright__text {
  font-size: 0.8em;
  color: #fff;
  text-align: center;
  margin: 0;
}

@media screen and (max-width: 600px) {
  .questionLink .footer__list {
    flex-direction: column;
    width: 70%;
  }

  .questionLink .footer__list li+li {
    margin-top: 0.5em;
  }
}

.questionLink {
  width: 100%;
  height: auto;
  font-size: min(16px, 3vw);
  text-align: center;
  color: #3f3a3b;
}

.questionLink .progress {
  width: 90%;
  height: auto;
  margin: 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
  column-gap: 2em;
}

.questionLink .progress .progress__item {
  width: 3em;
  height: 3em !important;
  background: transparent;
  border-radius: 1.5em;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #999;
  font-size: 1em;
  font-weight: bold;
  position: relative;
}

.questionLink .progress .progress__item:before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 1.5em;
  background: #eee;
  z-index: 1;
}

.questionLink .progress .progress__item span {
  position: relative;
  z-index: 2;
}

.questionLink .progress .progress__item.is-active {
  color: #fff;
}

.questionLink .progress .progress__item.is-active:before {
  background: #524646;
}

.questionLink .progress .progress__item:after {
  content: '';
  width: 5em;
  height: auto;
  display: block;
  border-top: 2px solid #eee;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 0;
}

.questionLink .progress .progress__item:first-of-type:after {
  width: 3em;
  transform: translate(0, -50%);
}

.questionLink .progress .progress__item:last-of-type:after {
  width: 3em;
  left: initial;
  right: 50%;
  transform: translate(0, -50%);
}

.questionLink .head {
  margin-top: 1.5em;
}

.questionLink .head .head__text {
  font-size: 1.2em;
  font-weight: 600;
  line-height: 1.5;
}

.questionLink .head .head__note {
  font-size: 0.7em;
  font-weight: normal;
  margin: 0.5em 0;
}

.questionLink .video {
  margin-top: 1.5em;
}

.questionLink .video .video__movie {
  width: 100%;
  height: auto;
}

.questionLink .video .video__time {
