}

.arrow {
  display: block;
  width: 20px;
  animation: tap-down 1.4s cubic-bezier(0.2, 0.9, 0.3, 1) infinite;
}

.arrow:nth-child(2) { animation-delay: 0.07s; }
.arrow:nth-child(3) { animation-delay: 0.14s; }

.arrow svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.arrow path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

@keyframes tap-down {
  0%, 100% { transform: translateY(0);   opacity: 0.55; }
  8%       { transform: translateY(6px); opacity: 1; }
  16%      { transform: translateY(0);   opacity: 0.7; }
  24%      { transform: translateY(6px); opacity: 1; }
  34%      { transform: translateY(0);   opacity: 0.55; }
}

@media (prefers-reduced-motion: reduce) {
  .arrow { animation: none; opacity: 0.7; }
}

/* ============================================================
   サンプル施策438 記事下部クーポン専用CSS
   対象：#sbq-bottom-coupon
   ============================================================ */


/* ============================================================
   未回答時は完全に非表示
   ============================================================ */

#sbq-bottom-coupon[hidden] {
  display: none !important;
}


/* ============================================================
   クーポン枠全体
   ============================================================ */

#sbq-bottom-coupon.sbq-bottom-coupon {
  width: 100%;
  max-width: 500px;
  margin: 22px auto 30px;
  padding: 26px 12px 18px;
  border: 1px solid #F1D5D0;
  border-radius: 18px;
  background:
    linear-gradient(
      180deg,
      #FFFDFC 0%,
      #FFF3F0 100%
    );
  color: #5A4038;
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Hiragino Kaku Gothic ProN",
    "Hiragino Sans",
    "Noto Sans JP",
    "Yu Gothic",
    sans-serif;
  box-sizing: border-box;
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity 0.45s ease,
    transform 0.45s ease;
}

#sbq-bottom-coupon.sbq-bottom-coupon.is-visible {
  opacity: 1;
  transform: translateY(0);
}

#sbq-bottom-coupon *,
#sbq-bottom-coupon *::before,
#sbq-bottom-coupon *::after {
  box-sizing: border-box;
}


/* ============================================================
   お礼テキスト
   ============================================================ */

#sbq-bottom-coupon .sbq-bottom-thanks {
  display: block;
  width: 100%;
  margin: 0 0 24px !important;
  padding: 0 !important;
  color: #4E342E !important;
  font-size: 21px !important;
  font-weight: 900 !important;
  line-height: 1.8 !important;
  letter-spacing: 0.02em !important;
  text-align: center !important;
}


/* ============================================================
   テキストのマーカー
   ============================================================ */

#sbq-bottom-coupon .sbq-bottom-marker {
  display: inline;
  padding: 0 5px 3px;
  background:
    linear-gradient(
      transparent 55%,
      #FFD1D2 55%,
      #FFD1D2 92%,
      transparent 92%
    );
  border-radius: 3px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}


/* ============================================================
   クーポン画像枠
   ============================================================ */

#sbq-bottom-coupon .sbq-bottom-ticket {
  display: block;
  width: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 14px;
  background: #FFFFFF;
  box-shadow:
    0 10px 28px
    rgba(141, 70, 58, 0.2);
  animation:
    sbqBottomCouponPop 0.6s
    cubic-bezier(0.34, 1.56, 0.64, 1)
    both;
}

#sbq-bottom-coupon .sbq-bottom-ticket img {
  display: block !important;
  width: 100% !important;
  max-width: none !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  user-select: none;
  -webkit-user-drag: none;
}

@keyframes sbqBottomCouponPop {
  0% {
    opacity: 0;
    transform: scale(0.93);
  }

  100% {
    opacity: 1;
    transform: scale(1);
  }
}


/* ============================================================
   小さいスマートフォン
   ============================================================ */

@media screen and (max-width: 359px) {
  #sbq-bottom-coupon.sbq-bottom-coupon {
    margin-top: 18px;
    margin-bottom: 24px;
    padding: 22px 8px 14px;
  }

  #sbq-bottom-coupon .sbq-bottom-thanks {
    margin-bottom: 20px !important;
    font-size: 18px !important;
    line-height: 1.75 !important;
  }

  #sbq-bottom-coupon .sbq-bottom-ticket {
    border-radius: 11px;
  }
}

/* ===== Instagram フィード風カード ===== */
.ig-post{
  --ig-w: 470px;          /* カード幅。LPで全幅にするなら 100% */
  --ig-fg: #262626;
  --ig-sub: #8e8e8e;
  --ig-accent: #0095f6;

  max-width: var(--ig-w);
  margin: 0 auto 24px;
  background: #fff;
  color: var(--ig-fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Hiragino Sans",
               "Hiragino Kaku Gothic ProN", "Noto Sans JP", Meiryo, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
.ig-post *{ box-sizing: border-box; }

/* --- ヘッダー --- */
.ig-post__head{
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 14px;
}
.ig-post__avatar{
  flex: 0 0 auto;
  width: 42px; height: 42px;
  padding: 2px;
  border-radius: 50%;
  background: #dbdbdb;
  display: block;
}
.ig-post__avatar.has-ring{
  background: conic-gradient(from 20deg,#f9ce34,#ee2a7b,#6228d7,#ee2a7b,#f9ce34);
}
.ig-post__avatar img{
  width: 100%; height: 100%;
  display: block;
  border-radius: 50%;
  border: 2px solid #fff;
  object-fit: cover;
}
.ig-post__id{
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
.ig-post__name{
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ig-post__verified{
  flex: 0 0 auto;
  width: 15px; height: 15px;
  fill: var(--ig-accent);
}
.ig-post__menu{
  margin-left: auto;
  flex: 0 0 auto;
  width: 26px; height: 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.ig-post__menu i{
  display: block;
  height: 2.5px;
  border-radius: 2px;
  background: #262626;
}

/* --- 画像（正方形固定） --- */
.ig-post__media{
  position: relative;
  aspect-ratio: 1 / 1;     /* 枠側で正方形を確定 */
  overflow: hidden;
  background: #fafafa;
}
.ig-post__media img{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;       /* 非正方形画像は中央基準でトリミング */
  display: block;
}
@supports not (aspect-ratio: 1 / 1){
  .ig-post__media{ padding-top: 100%; }
}
.ig-post__counter{
  position: absolute;
  top: 12px; right: 12px;
  z-index: 2;
  padding: 6px 11px;
  border-radius: 999px;
  background: rgba(26,26,26,.6);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: .02em;
}

/* --- インジケーター --- */
.ig-post__dots{
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 12px 0 2px;
}
.ig-post__dots i{
  display: block;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #c7c7c7;
}
.ig-post__dots i.is-active{ background: var(--ig-accent); }
.ig-post__dots i.is-sm{ width: 5px; height: 5px; }
.ig-post__dots i.is-xs{ width: 4px; height: 4px; }

/* --- アクション --- */
.ig-post__actions{
  display: flex;
  align-items: center;
  gap: 17px;
  padding: 6px 14px 4px;
}
.ig-post__btn{
  display: flex;
  align-items: center;
  color: #262626;
}
.ig-post__btn svg{
  width: 26px; height: 26px;
  display: block;
}
.ig-post__repost{ gap: 6px; }
.ig-post__repost b{
  font-size: 15px;
  font-weight: 600;
  line-height: 1;
}
.ig-post__save{ margin-left: auto; }

/* --- テキスト --- */
.ig-post__body{
  padding: 4px 14px 18px;
  font-size: 14px;
  line-height: 1.5;
}
.ig-post__likes{
  margin: 0 0 3px;
  font-weight: 600;
}
.ig-post__caption{
  margin: 0;
  word-break: break-word;
}
.ig-post__caption-name{
  font-weight: 600;
  margin-right: 5px;
}
.ig-post__more{
  color: var(--ig-sub);
  margin-left: 3px;
}
.ig-post__date{
  margin: 7px 0 0;
  font-size: 12px;
  color: #a8a8a8;
}

/* ===== 2枚スライダー ===== */
.sbSlider{
  position:relative;
  max-width:580px;
  margin:0 auto 24px;
  -webkit-tap-highlight-color:transparent;
}
.sbSlider *{box-sizing:border-box;}
.sbSlider__stage{position:relative;}

/* 横スクロール本体 */
.sbSlider__viewport{
  overflow-x:auto;
  overflow-y:hidden;
  scroll-snap-type:x mandatory;
  overscroll-behavior-x:contain;      /* iOSの「戻る」暴発を防ぐ＝離脱防止 */
  -webkit-overflow-scrolling:touch;
  scrollbar-width:none;
  -ms-overflow-style:none;
}
.sbSlider__viewport::-webkit-scrollbar{display:none;}

.sbSlider__track{display:flex;gap:8px;}

/* 1枚 */
.sbSlider__slide{
  position:relative;
  flex:0 0 88%;                        /* 残り12%を2枚目のチラ見せに使う */
  scroll-snap-align:center;
  scroll-snap-stop:always;
  border-radius:14px;
  overflow:hidden;
  background:#f1f1f1;
  cursor:pointer;
}
.sbSlider__slide img{
  display:block;
  width:100%;
  height:auto;
  aspect-ratio:1/1;                    /* 正方形固定＝読込時のガタつき0 */
  object-fit:cover;
  user-select:none;
  -webkit-user-drag:none;
}

/* ラベル */
.sbSlider__badge{
  position:absolute;top:10px;left:10px;z-index:2;
  padding:5px 13px;
  border-radius:999px;
  font-size:13px;font-weight:700;letter-spacing:.04em;
  color:#fff;background:rgba(85,85,85,.82);
}
.sbSlider__badge.is-after{background:#ff6161;}

/* 矢印 */
.sbSlider__arrow{
  position:absolute;top:50%;right:2.5%;z-index:3;
  width:42px;height:42px;padding:0;
  transform:translateY(-50%);
  border:0;border-radius:50%;
  background:rgba(255,255,255,.94);
  box-shadow:0 2px 10px rgba(0,0,0,.18);
  cursor:pointer;
  opacity:1;transition:opacity .3s;
  animation:sbPulse 1.6s ease-in-out infinite;
}
.sbSlider__arrow::before{
  content:"";display:block;
  width:10px;height:10px;margin:0 auto;
  border-top:2.5px solid #ff6161;
  border-right:2.5px solid #ff6161;
  transform:translateX(-2px) rotate(45deg);
}
.sbSlider.is-end .sbSlider__arrow{opacity:0;pointer-events:none;animation:none;}
@keyframes sbPulse{
  0%,100%{transform:translateY(-50%) translateX(0);}
  50%    {transform:translateY(-50%) translateX(-5px);}
}

/* スワイプ促しヒント */
.sbSlider__hint{
  position:absolute;left:50%;bottom:12px;z-index:3;
  transform:translateX(-50%);
  padding:6px 15px;
  border-radius:999px;
  background:rgba(0,0,0,.58);
  color:#fff;font-size:12px;font-weight:600;
  white-space:nowrap;pointer-events:none;
  transition:opacity .4s;
}
.sbSlider.is-moved .sbSlider__hint{opacity:0;}

/* ドット＋カウンタ */
.sbSlider__ui{
  display:flex;align-items:center;justify-content:center;
  gap:14px;margin-top:12px;
}
.sbSlider__dots{display:flex;align-items:center;gap:8px;}
.sbSlider__dot{
  width:8px;height:8px;padding:0;border:0;border-radius:50%;
  background:#d8d8d8;cursor:pointer;
  transition:width .25s,background .25s;
}
.sbSlider__dot.is-active{width:22px;border-radius:999px;background:#ff6161;}
.sbSlider__count{font-size:13px;color:#999;font-weight:600;}
.sbSlider__count b{color:#ff6161;font-size:15px;}

@media (prefers-reduced-motion:reduce){
  .sbSlider__arrow{animation:none;}
  .sbSlider__viewport{scroll-behavior:auto;}
}

/* ============================================================
   サンプル施策438 診断アンケート ― CSS欄
   ------------------------------------------------------------
   ・CSS変数は使用していません（エディタのリンター対策）
   ・すべて #sbq-root 配下にスコープ済み。既存CSSと衝突しません
   ・CSS欄が使用中の場合は「末尾に追記」してください
   ============================================================ */

#sbq-root{
  max-width:500px;
  margin:0 auto;
  padding:0;
  color:#5A4038;
  font-family:-apple-system,BlinkMacSystemFont,"Hiragino Kaku Gothic ProN","Hiragino Sans","Noto Sans JP","Yu Gothic",sans-serif;
  -webkit-font-smoothing:antialiased;
  -webkit-text-size-adjust:100%;
  line-height:1.6;
}
#sbq-root *,
#sbq-root *::before,
#sbq-root *::after{
  box-sizing:border-box;
  -webkit-tap-highlight-color:transparent;
}
#sbq-root button{
  font-family:inherit;
  margin:0;
}

#sbq-root .sbq-frame{
  background:#F7EDE8;
  border-radius:18px;
  overflow:hidden;
  padding:0 0 18px;
}

/* ---------- ステップ切替 ---------- */
#sbq-root .sbq-step{display:none;}
#sbq-root .sbq-step.is-active{
  display:block;
  animation:sbqIn 0.28s ease-out both;
}
@keyframes sbqIn{
  from{opacity:0;transform:translateY(10px);}
  to{opacity:1;transform:translateY(0);}
}

/* ---------- 設問画像（縦横比を固定してガタつき防止） ---------- */
#sbq-root .sbq-media{
  position:relative;
  width:100%;
  height:0;
  padding-top:100%;
  background:#F7EDE8;
  overflow:hidden;
}
#sbq-root .sbq-img{
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:100%;
  display:block;
  object-fit:cover;
}

/* ---------- 選択肢 ---------- */
#sbq-root .sbq-hint{
  margin:14px 16px -2px;
  font-size:12.5px;
  font-weight:700;
  text-align:center;
  color:#D99A8E;
}
#sbq-root .sbq-opts{padding:14px 16px 0;}

#sbq-root .sbq-opt{
  position:relative;
  display:block;
  width:100%;
  min-height:56px;
  margin:0 0 10px;
  padding:16px 18px 16px 46px;
  border:1.5px solid #EBD9D2;
  border-radius:999px;
  background:#FFFFFF;
  color:#5A4038;
  font-size:16px;
  font-weight:700;
  letter-spacing:0.02em;
  text-align:left;
  cursor:pointer;
  -webkit-appearance:none;
  appearance:none;
  touch-action:manipulation;
  -webkit-user-select:none;
  user-select:none;
  transition:background 0.16s ease,border-color 0.16s ease,color 0.16s ease,transform 0.1s ease;
}
#sbq-root .sbq-opt::before{
  content:"";
  position:absolute;
  left:16px;
  top:50%;
  width:18px;
  height:18px;
  margin-top:-9px;
  border:1.5px solid #F4C6C0;
  border-radius:50%;
  background:#FFFFFF;
  transition:background 0.16s ease,border-color 0.16s ease;
}
#sbq-root .sbq-opt::after{
  content:"";
  position:absolute;
  left:21px;
  top:50%;
  width:8px;
  height:8px;
  margin-top:-4px;
  border-radius:50%;
  background:#FFFFFF;
  transform:scale(0);
  transition:transform 0.16s cubic-bezier(0.34,1.56,0.64,1);
}
#sbq-root .sbq-opt:active{transform:scale(0.985);}
#sbq-root .sbq-opt.is-on{
  background:#D99A8E;
  border-color:#D99A8E;
  color:#FFFFFF;
}
#sbq-root .sbq-opt.is-on::before{
  background:rgba(255,255,255,0.25);
  border-color:#FFFFFF;
}
#sbq-root .sbq-opt.is-on::after{transform:scale(1);}

/* ---------- 複数選択用の「次へ」 ---------- */
#sbq-root .sbq-next{
  display:block;
  width:calc(100% - 32px);
  margin:4px 16px 0;
  min-height:54px;
  border:0;
  border-radius:999px;
  background:#5A4038;
  color:#FFFFFF;
  font-size:16px;
  font-weight:800;
  letter-spacing:0.06em;
  cursor:pointer;
  touch-action:manipulation;
  transition:opacity 0.2s ease,transform 0.1s ease;
}
#sbq-root .sbq-next:disabled{
  opacity:0.28;
  pointer-events:none;
}
#sbq-root .sbq-next:active{transform:scale(0.985);}

/* ---------- 解析中 ---------- */
#sbq-root .sbq-loading{
  padding:56px 24px 64px;
  text-align:center;
}
#sbq-root .sbq-load-ring{
  width:44px;
  height:44px;
  margin:0 auto 18px;
  border:3px solid #F4C6C0;
  border-top-color:#D99A8E;
  border-radius:50%;
  animation:sbqSpin 0.9s linear infinite;
}
@keyframes sbqSpin{
  from{transform:rotate(0deg);}
  to{transform:rotate(360deg);}
}
#sbq-root .sbq-load-txt{
  margin:0 0 20px;
  font-size:15px;
  font-weight:700;
}
#sbq-root .sbq-dots i{
  font-style:normal;
  opacity:0;
  animation:sbqDot 1.2s infinite;
}
#sbq-root .sbq-dots i:nth-child(2){animation-delay:0.2s;}
#sbq-root .sbq-dots i:nth-child(3){animation-delay:0.4s;}
@keyframes sbqDot{
  0%{opacity:0;}
  30%{opacity:1;}
  60%{opacity:0;}
  100%{opacity:0;}
}
#sbq-root .sbq-load-bar{
  width:70%;
  max-width:220px;
  height:5px;
  margin:0 auto;
  border-radius:99px;
  background:#FFFFFF;
  overflow:hidden;
}
#sbq-root .sbq-load-bar span{
  display:block;
  width:100%;
  height:100%;
  background:#D99A8E;
  transform:scaleX(0);
  transform-origin:left center;
  transition:transform 1.5s linear;
}
#sbq-root .sbq-load-bar.is-run span{transform:scaleX(1);}

/* ---------- 結果（クーポン画面） ---------- */
#sbq-root .sbq-result{padding:26px 16px 6px;}

#sbq-root .sbq-thanks-ttl{
  margin:0 0 4px;
  font-size:19px;
  font-weight:800;
  line-height:1.5;
  text-align:center;
}
#sbq-root .sbq-thanks-sub{
  margin:0 0 18px;
  font-size:13px;
  font-weight:700;
  line-height:1.6;
  text-align:center;
  color:#D99A8E;
}

#sbq-root .sbq-ticket{
  margin:0 0 20px;
  animation:sbqPop 0.55s cubic-bezier(0.34,1.56,0.64,1) both;
}
#sbq-root .sbq-ticket img{
  width:100%;
  height:auto;
  display:block;
}
@keyframes sbqPop{
  0%{opacity:0;transform:scale(0.88);}
  100%{opacity:1;transform:scale(1);}
}

/* ---------- 下へ誘導するシェブロン（不要なら削除可） ---------- */
#sbq-root .sbq-scroll{
  width:16px;
  height:16px;
  margin:24px auto 8px;
  border-right:2.5px solid #D99A8E;
  border-bottom:2.5px solid #D99A8E;
  opacity:0.65;
  animation:sbqBounce 1.7s ease-in-out infinite;
}
@keyframes sbqBounce{
  0%{transform:rotate(45deg) translate(0,0);}
  50%{transform:rotate(45deg) translate(4px,4px);}
  100%{transform:rotate(45deg) translate(0,0);}
}

@media screen and (max-width:359px){
  #sbq-root .sbq-opt{
    font-size:14.5px;
    min-height:52px;
    padding-left:42px;
  }
  #sbq-root .sbq-thanks-ttl{font-size:17px;}

}

/* ============================================================
   サンプル施策438 診断アンケート ― CSS欄
   ------------------------------------------------------------
   ・CSS変数は使用していません（エディタのリンター対策）
   ・すべて #sbq-root 配下にスコープ済み。既存CSSと衝突しません
   ・CSS欄が使用中の場合は「末尾に追記」してください
   ============================================================ */

#sbq-root{
  max-width:500px;
  margin:0 auto;
  padding:0;
  color:#5A4038;
  font-family:-apple-system,BlinkMacSystemFont,"Hiragino Kaku Gothic ProN","Hiragino Sans","Noto Sans JP","Yu Gothic",sans-serif;
  -webkit-font-smoothing:antialiased;
  -webkit-text-size-adjust:100%;
  line-height:1.6;
}
#sbq-root *,
#sbq-root *::before,
#sbq-root *::after{
  box-sizing:border-box;
  -webkit-tap-highlight-color:transparent;
}
#sbq-root button{
  font-family:inherit;
  margin:0;
}

#sbq-root .sbq-frame{
  background:#F7EDE8;
  border-radius:18px;
  overflow:hidden;
  padding:0 0 18px;
}

/* ---------- ステップ切替 ---------- */
#sbq-root .sbq-step{display:none;}
#sbq-root .sbq-step.is-active{
  display:block;
  animation:sbqIn 0.28s ease-out both;
}
@keyframes sbqIn{
  from{opacity:0;transform:translateY(10px);}
  to{opacity:1;transform:translateY(0);}
}

/* ---------- 設問画像（縦横比を固定してガタつき防止） ---------- */
#sbq-root .sbq-media{
  position:relative;
  width:100%;
  height:0;
  padding-top:100%;
  background:#F7EDE8;
  overflow:hidden;
}
#sbq-root .sbq-img{
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:100%;
  display:block;
  object-fit:cover;
}

/* ---------- 選択肢 ---------- */
#sbq-root .sbq-hint{
  margin:14px 16px -2px;
  font-size:12.5px;
  font-weight:700;
  text-align:center;
  color:#D99A8E;
}
#sbq-root .sbq-opts{padding:14px 16px 0;}

#sbq-root .sbq-opt{
  position:relative;
  display:block;
  width:100%;
  min-height:56px;
  margin:0 0 10px;
  padding:16px 18px 16px 46px;
  border:1.5px solid #EBD9D2;
  border-radius:999px;
  background:#FFFFFF;
  color:#5A4038;
  font-size:16px;
  font-weight:700;
  letter-spacing:0.02em;
  text-align:left;
  cursor:pointer;
  -webkit-appearance:none;
  appearance:none;
  touch-action:manipulation;
  -webkit-user-select:none;
  user-select:none;
  transition:background 0.16s ease,border-color 0.16s ease,color 0.16s ease,transform 0.1s ease;
}
#sbq-root .sbq-opt::before{
  content:"";
  position:absolute;
  left:16px;
  top:50%;
  width:18px;
  height:18px;
  margin-top:-9px;
  border:1.5px solid #F4C6C0;
  border-radius:50%;
  background:#FFFFFF;
  transition:background 0.16s ease,border-color 0.16s ease;
}
#sbq-root .sbq-opt::after{
  content:"";
  position:absolute;
  left:21px;
  top:50%;
  width:8px;
  height:8px;
  margin-top:-4px;
  border-radius:50%;
  background:#FFFFFF;
  transform:scale(0);
  transition:transform 0.16s cubic-bezier(0.34,1.56,0.64,1);
}
#sbq-root .sbq-opt:active{transform:scale(0.985);}
#sbq-root .sbq-opt.is-on{
  background:#D99A8E;
  border-color:#D99A8E;
  color:#FFFFFF;
}
#sbq-root .sbq-opt.is-on::before{
  background:rgba(255,255,255,0.25);
  border-color:#FFFFFF;
}
#sbq-root .sbq-opt.is-on::after{transform:scale(1);}

/* ---------- 複数選択用の「次へ」 ---------- */
#sbq-root .sbq-next{
  display:block;
  width:calc(100% - 32px);
  margin:4px 16px 0;
  min-height:54px;
  border:0;
  border-radius:999px;
  background:#5A4038;
  color:#FFFFFF;
  font-size:16px;
  font-weight:800;
  letter-spacing:0.06em;
  cursor:pointer;
  touch-action:manipulation;
  transition:opacity 0.2s ease,transform 0.1s ease;
}
#sbq-root .sbq-next:disabled{
  opacity:0.28;
  pointer-events:none;
}
#sbq-root .sbq-next:active{transform:scale(0.985);}

/* ---------- 解析中 ---------- */
#sbq-root .sbq-loading{
  padding:56px 24px 64px;
  text-align:center;
}
#sbq-root .sbq-load-ring{
  width:44px;
  height:44px;
  margin:0 auto 18px;
  border:3px solid #F4C6C0;
  border-top-color:#D99A8E;
  border-radius:50%;
  animation:sbqSpin 0.9s linear infinite;
}
@keyframes sbqSpin{
  from{transform:rotate(0deg);}
  to{transform:rotate(360deg);}
}
#sbq-root .sbq-load-txt{
  margin:0 0 20px;
  font-size:15px;
  font-weight:700;
}
#sbq-root .sbq-dots i{
  font-style:normal;
  opacity:0;
  animation:sbqDot 1.2s infinite;
}
#sbq-root .sbq-dots i:nth-child(2){animation-delay:0.2s;}
#sbq-root .sbq-dots i:nth-child(3){animation-delay:0.4s;}
@keyframes sbqDot{
  0%{opacity:0;}
  30%{opacity:1;}
  60%{opacity:0;}
  100%{opacity:0;}
}
#sbq-root .sbq-load-bar{
  width:70%;
  max-width:220px;
  height:5px;
  margin:0 auto;
  border-radius:99px;
  background:#FFFFFF;
  overflow:hidden;
}
#sbq-root .sbq-load-bar span{
  display:block;
  width:100%;
  height:100%;
  background:#D99A8E;
  transform:scaleX(0);
  transform-origin:left center;
  transition:transform 1.5s linear;
}
#sbq-root .sbq-load-bar.is-run span{transform:scaleX(1);}

/* ---------- 結果 ---------- */
#sbq-root .sbq-result{padding:18px 16px 4px;}
#sbq-root .sbq-card{
  background:#FFFFFF;
  border:1.5px solid #F4C6C0;
  border-radius:20px;
  padding:24px 20px;
}
#sbq-root .sbq-eyebrow{
  margin:0 0 6px;
  font-size:12px;
  font-weight:700;
  letter-spacing:0.16em;
  color:#D99A8E;
  text-align:center;
}
#sbq-root .sbq-type{
  margin:0 0 14px;
  font-size:21px;
  font-weight:800;
  line-height:1.45;
  letter-spacing:0.01em;
  text-align:center;
}
#sbq-root .sbq-tags{
  margin:0 0 10px;
  text-align:center;
}
#sbq-root .sbq-tag{
  display:inline-block;
  margin:0 3px 6px;
  padding:5px 12px;
  border-radius:99px;
  background:#F7EDE8;
  font-size:12px;
  font-weight:700;
}
#sbq-root .sbq-body{
  margin:0;
  font-size:14.5px;
  line-height:1.85;
  white-space:pre-line;
  overflow-wrap:break-word;
}
#sbq-root .sbq-divider{
  height:1px;
  margin:18px 0;
  background:#EBD9D2;
}
#sbq-root .sbq-lead{
  margin:0;
  font-size:15px;
  font-weight:800;
  line-height:1.75;
  text-align:center;
}
#sbq-root .sbq-lead b{color:#D99A8E;}

#sbq-root .sbq-coupon{
  margin:18px 0 12px;
  padding:14px;
  border:1.5px dashed #D99A8E;
  border-radius:14px;
  background:#FFFFFF;
  text-align:center;
}
#sbq-root .sbq-coupon-t{
  margin:0 0 3px;
  font-size:15px;
  font-weight:800;
  color:#D99A8E;
}
#sbq-root .sbq-coupon-s{
  margin:0;
  font-size:11.5px;
  opacity:0.75;
}

#sbq-root .sbq-cta{
  display:block;
  padding:17px 16px;
  border-radius:999px;
  background:#D99A8E;
  color:#FFFFFF;
  text-decoration:none;
  text-align:center;
  box-shadow:0 6px 16px rgba(217,154,142,0.42);
  animation:sbqPulse 1.9s ease-in-out infinite;
}
#sbq-root .sbq-cta-main{
  display:block;
  font-size:18px;
  font-weight:800;
  letter-spacing:0.03em;
}
#sbq-root .sbq-cta-sub{
  display:block;
  margin-top:3px;
  font-size:11.5px;
  opacity:0.9;
}
@keyframes sbqPulse{
  0%{transform:scale(1);}
  50%{transform:scale(1.025);}
  100%{transform:scale(1);}
}
#sbq-root .sbq-note{
  margin:10px 0 0;
  font-size:10.5px;
  line-height:1.6;
  text-align:center;
  opacity:0.6;
}

@media screen and (max-width:359px){
  #sbq-root .sbq-opt{
    font-size:14.5px;
    min-height:52px;
    padding-left:42px;
  }
  #sbq-root .sbq-type{font-size:19px;}
}
